'use strict';const crypto=require('node:crypto'),MAGIC=Buffer.from('VYBOTENC2');function key(){const s=process.env.DISCORD_TOKEN||process.env.TOKEN;if(!s||s.length<20)throw Error('DISCORD_TOKEN gerekli');return crypto.hkdfSync('sha256',Buffer.from(s),Buffer.from('vybot-eaa77e0f1551fadd'),Buffer.from('source-v2'),32)}function encrypt(p){const n=crypto.randomBytes(12),c=crypto.createCipheriv('aes-256-gcm',key(),n);c.setAAD(MAGIC);return Buffer.concat([MAGIC,n,c.update(p),c.final(),c.getAuthTag()])}function decrypt(b){if(!b.subarray(0,MAGIC.length).equals(MAGIC))throw Error('Geçersiz paket');const n=b.subarray(9,21),tag=b.subarray(-16),d=crypto.createDecipheriv('aes-256-gcm',key(),n);d.setAAD(MAGIC);d.setAuthTag(tag);return Buffer.concat([d.update(b.subarray(21,-16)),d.final()])}module.exports={encrypt,decrypt};
